c='p3';B='CSDL 2'
S=[]
S.append(TITLE('TIN HỌC · CƠ SỞ DỮ LIỆU 2','KHOÁ, RÀNG BUỘC<br>VÀ KIỂU DỮ LIỆU','Khoá chính, khoá ngoài, toàn vẹn tham chiếu, NOT NULL, UNIQUE, CHECK, DEFAULT, kiểu dữ liệu SQL.',['PRIMARY KEY','FOREIGN KEY','NOT NULL','CHECK','kiểu dữ liệu']))
S.append(goals(c,B,['Phân biệt <b>khoá chính, khoá ngoài, khoá ứng viên</b>.','Hiểu <b>toàn vẹn tham chiếu</b> giữa hai bảng.','Dùng <b>NOT NULL, UNIQUE, CHECK, DEFAULT</b> khi tạo bảng.','Chọn <b>kiểu dữ liệu</b> phù hợp: INT, REAL, VARCHAR, DATE…','Viết lệnh <b>CREATE TABLE</b> hoàn chỉnh.'],['Khoá chính','Khoá ngoài, tham chiếu','Ràng buộc toàn vẹn','Kiểu dữ liệu','Trọng tâm, HSG']))
S.append(S2(c,B+' · 1','Khoá chính (PRIMARY KEY)',card('Định nghĩa',ul(['<b>Khoá chính</b>: trường (hoặc nhóm trường) có giá trị <b>duy nhất</b>, <b>không rỗng</b>, xác định <b>một bản ghi</b>.','Mỗi bảng có <b>tối đa một</b> khoá chính.','Ví dụ: <b>MAHS</b> của HOCSINH, <b>MALOP</b> của LOP.'],6)),KEY('Không chọn <b>họ tên</b> làm khoá chính vì có thể <b>trùng tên</b>. Nên dùng <b>mã</b> (mã học sinh, số căn cước).')+OK('<b>Khoá ứng viên</b>: mọi tập trường có thể làm khoá; khoá chính là một khoá ứng viên được chọn.')))
S.append(SQ(c,B+' · 1','Khoá chính chống trùng','INSERT INTO hocsinh VALUES(\'HS01\',\'Khoa\',\'12A\',\'Nam\',8)',KEY('Thêm bản ghi có <b>MAHS = HS01</b> đã tồn tại → HQTCSDL <b>từ chối</b> (vi phạm UNIQUE của khoá chính).')+WARN('Thông báo lỗi tiếng Anh của SQLite: “UNIQUE constraint failed”.'),20))
S.append(S2(c,B+' · 1','Khoá phức hợp',card('Khi một trường không đủ',ul(['Bảng <b>DIEM(mahs, mamon, diem)</b>: một học sinh có nhiều môn, một môn nhiều học sinh.','Cặp <b>(mahs, mamon)</b> mới xác định duy nhất một dòng điểm.','Đó là <b>khoá chính phức hợp</b>.'],6)),CODE('CREATE TABLE diem(\n  mahs  TEXT,\n  mamon TEXT,\n  diem  REAL,\n  PRIMARY KEY (mahs, mamon)\n);',22)))
S.append(S2(c,B+' · 2','Khoá ngoài (FOREIGN KEY)',card('Định nghĩa',ul(['<b>Khoá ngoài</b>: trường trong bảng này <b>tham chiếu</b> khoá chính của bảng khác.','Thể hiện <b>mối liên kết</b> giữa hai bảng.','Ví dụ: <b>HOCSINH.lop</b> tham chiếu <b>LOP.malop</b>.'],6)),RES('<svg viewBox="0 0 520 250" style="width:100%"><g font-family="sans-serif" font-weight="800" text-anchor="middle" font-size="22"><rect x="10" y="20" width="220" height="40" fill="#6A1B9A"/><text x="120" y="48" fill="#fff">HOCSINH</text><rect x="10" y="60" width="220" height="150" fill="#F3E5F5" stroke="#6A1B9A" stroke-width="3"/><text x="120" y="92" fill="#0B2545">mahs (PK)</text><text x="120" y="125" fill="#0B2545">hoten</text><rect x="14" y="135" width="212" height="34" fill="#FFF59D"/><text x="120" y="160" fill="#C62828">lop (FK)</text><text x="120" y="195" fill="#0B2545">diemtb</text><rect x="290" y="20" width="220" height="40" fill="#6A1B9A"/><text x="400" y="48" fill="#fff">LOP</text><rect x="290" y="60" width="220" height="110" fill="#F3E5F5" stroke="#6A1B9A" stroke-width="3"/><rect x="294" y="68" width="212" height="34" fill="#C8E6C9"/><text x="400" y="93" fill="#2E7D32">malop (PK)</text><text x="400" y="128" fill="#0B2545">tenlop</text><text x="400" y="158" fill="#0B2545">gvcn</text><path d="M226 152 L290 85" stroke="#C62828" stroke-width="4"/><path d="M276 85 L290 85 L284 100" stroke="#C62828" stroke-width="4" fill="none"/></g></svg>','Quan hệ khoá ngoài → khoá chính')))
S.append(SQ(c,B+' · 2','Bảng có khoá ngoài','SELECT h.hoten, h.lop, l.tenlop\nFROM hocsinh h JOIN lop l ON h.lop = l.malop\nWHERE h.lop = \'12A\'',KEY('Giá trị <b>lop</b> trong HOCSINH phải là một <b>malop có thật</b> trong LOP: đó là <b>toàn vẹn tham chiếu</b>.'),21))
S.append(S2(c,B+' · 2','Toàn vẹn tham chiếu',card('Quy tắc',ul(['Giá trị khoá ngoài phải <b>có sẵn</b> làm khoá chính ở bảng được tham chiếu (hoặc NULL nếu cho phép).','<b>Không thêm</b> học sinh thuộc lớp chưa tồn tại.','<b>Không xoá</b> lớp còn học sinh (trừ khi cấu hình xoá dây chuyền).'],6)),KEY('Tuỳ chọn: <b>ON DELETE CASCADE</b> (xoá bảng cha thì xoá luôn con), <b>SET NULL</b>, <b>RESTRICT</b> (cấm xoá).')+WARN('Thứ tự: tạo bảng <b>cha</b> (LOP) trước bảng <b>con</b> (HOCSINH); nhập dữ liệu bảng cha trước.')))
S.append(SQ(c,B+' · 2','Vi phạm khoá ngoài bị từ chối','INSERT INTO hocsinh2 VALUES(\'HS09\',\'Lan\',\'13Z\')',KEY('Lớp <b>13Z</b> không tồn tại trong LOP nên lệnh bị từ chối: <b>FOREIGN KEY constraint failed</b>.'),21,setup="PRAGMA foreign_keys=ON;\nCREATE TABLE lop(malop TEXT PRIMARY KEY);\nINSERT INTO lop VALUES('12A'),('12B');\nCREATE TABLE hocsinh2(mahs TEXT PRIMARY KEY, hoten TEXT, lop TEXT REFERENCES lop(malop));"))
S.append(TB(c,B+' · 2','So sánh khoá chính và khoá ngoài',['','Khoá chính','Khoá ngoài'],[['Số lượng trong bảng','<b>một</b>','có thể <b>nhiều</b>'],['Giá trị trùng','<b>không</b>','<b>được</b> (nhiều học sinh cùng lớp)'],['Giá trị rỗng (NULL)','<b>không</b>','có thể (nếu cho phép)'],['Tác dụng','nhận diện bản ghi','liên kết hai bảng']],note=KEY('Nhớ: khoá chính là <b>“chứng minh thư”</b> của dòng; khoá ngoài là <b>“số chứng minh thư của người khác”</b> dùng để tham chiếu.')))
S.append(S2(c,B+' · 3','Các ràng buộc toàn vẹn thường dùng',T(tr('Ràng buộc','Ý nghĩa','Ví dụ',h=True)+tr('<code>PRIMARY KEY</code>','duy nhất, không rỗng','<code>mahs TEXT PRIMARY KEY</code>')+tr('<code>NOT NULL</code>','không được rỗng','<code>hoten TEXT NOT NULL</code>')+tr('<code>UNIQUE</code>','không trùng','<code>email TEXT UNIQUE</code>')+tr('<code>CHECK</code>','thoả điều kiện','<code>CHECK (diem BETWEEN 0 AND 10)</code>')+tr('<code>DEFAULT</code>','giá trị mặc định','<code>lop TEXT DEFAULT \'12A\'</code>')+tr('<code>FOREIGN KEY</code>','tham chiếu bảng khác','<code>REFERENCES lop(malop)</code>')),KEY('Ràng buộc giúp <b>bảo vệ tính đúng đắn</b> của dữ liệu ngay tại CSDL, không phụ thuộc ứng dụng.')))
S.append(SQ(c,B+' · 3','CREATE TABLE đầy đủ ràng buộc','INSERT INTO sv(ma,ten,diem) VALUES (2,\'Binh\',11)',KEY('Điểm 11 vi phạm <b>CHECK (diem BETWEEN 0 AND 10)</b> → bị từ chối: <b>CHECK constraint failed</b>.')+OK('Bảng: <code>CREATE TABLE sv(ma INTEGER PRIMARY KEY, ten TEXT NOT NULL, diem REAL CHECK (diem BETWEEN 0 AND 10), lop TEXT DEFAULT \'12A\')</code>'),20,setup="CREATE TABLE sv(ma INTEGER PRIMARY KEY, ten TEXT NOT NULL, diem REAL CHECK (diem BETWEEN 0 AND 10), lop TEXT DEFAULT '12A');\nINSERT INTO sv(ma,ten,diem) VALUES (1,'An',9);"))
S.append(SQ(c,B+' · 3','NOT NULL và DEFAULT','SELECT * FROM sv',KEY('Thêm <code>INSERT INTO sv(ma,ten) VALUES (3,\'Chi\')</code> không nêu <b>lop</b> và <b>diem</b> thì <b>lop</b> nhận giá trị mặc định <b>12A</b>, <b>diem</b> là NULL.')+WARN('Quên <b>ten</b> (NOT NULL) sẽ báo lỗi.'),21,setup="CREATE TABLE sv(ma INTEGER PRIMARY KEY, ten TEXT NOT NULL, diem REAL, lop TEXT DEFAULT '12A');\nINSERT INTO sv(ma,ten,diem) VALUES (1,'An',9);\nINSERT INTO sv(ma,ten) VALUES (3,'Chi');"))
S.append(S2(c,B+' · 3','Giá trị NULL',card('NULL là gì',ul(['<b>NULL</b> = “chưa biết / không có giá trị”, <b>khác 0</b> và khác xâu rỗng.','So sánh với NULL phải dùng <b>IS NULL / IS NOT NULL</b>, <b>không dùng =</b>.','Các hàm tổng hợp (AVG, SUM…) <b>bỏ qua NULL</b>.'],6)),CODE('SELECT * FROM sv WHERE diem IS NULL;\n-- đúng\nSELECT * FROM sv WHERE diem = NULL;\n-- sai: không trả về dòng nào',20)))
S.append(TB(c,B+' · 4','Các kiểu dữ liệu thông dụng trong SQL',['Nhóm','Kiểu','Ví dụ'],[['Số nguyên','<code>INT, INTEGER, BIGINT</code>','12, -5'],['Số thực','<code>REAL, FLOAT, DECIMAL(p,s)</code>','7.5'],['Xâu kí tự','<code>CHAR(n), VARCHAR(n), TEXT</code>','\'An\', \'12A\''],['Ngày giờ','<code>DATE, TIME, DATETIME</code>','\'2026-11-24\''],['Logic','<code>BOOLEAN</code>','TRUE, FALSE']],mono=1,note=KEY('Chọn kiểu theo <b>ý nghĩa</b>: mã học sinh dạng chữ (VARCHAR), điểm (REAL/DECIMAL), ngày sinh (DATE), số lượng (INT).')))
S.append(S2(c,B+' · 4','CHAR và VARCHAR',T(tr('','CHAR(n)','VARCHAR(n)',h=True)+tr('Độ dài','<b>cố định</b> n kí tự','<b>thay đổi</b> tối đa n')+tr('Bộ nhớ','luôn n','đúng độ dài dữ liệu (+ phụ)')+tr('Dùng cho','mã cố định (mã vùng, giới tính)','họ tên, địa chỉ')),KEY('<b>VARCHAR(50)</b> cho họ tên; <b>CHAR(1)</b> cho giới tính (M/F).')+OK('Kiểu <b>DECIMAL(10,2)</b> lưu tiền chính xác (10 chữ số, 2 chữ số thập phân), tránh sai số số thực.')))
S.append(SQ(c,B+' · 4','Kiểu dữ liệu trong thực tế: ngày tháng','SELECT hoten, date(\'2026-11-24\') AS hom_nay, date(\'2026-11-24\', \'+30 day\') AS sau_30_ngay FROM hocsinh LIMIT 2',KEY('Kiểu <b>DATE</b> cho phép <b>so sánh, cộng trừ ngày</b>. Chuỗi ngày chuẩn: <b>YYYY-MM-DD</b>.'),19))
S.append(S2(c,B+' · 4','Thiết kế bảng: ví dụ thư viện',card('Hai bảng SACH và MUON',ul(['<b>SACH</b>(<b>masach</b> PK, tensach, tacgia, namxb)','<b>BANDOC</b>(<b>mabd</b> PK, hoten, ngaysinh)','<b>MUON</b>(<b>mabd</b> FK, <b>masach</b> FK, ngaymuon, ngaytra)','Khoá chính MUON: (mabd, masach, ngaymuon)'],6)),KEY('Mối quan hệ <b>nhiều – nhiều</b> (một bạn đọc mượn nhiều sách; một sách nhiều lần mượn) cần <b>bảng trung gian</b> MUON.')))
S.append(S2(c,B+' · 4','Quy trình thiết kế CSDL',card('Các bước',ul(['<b>Xác định yêu cầu</b>: lưu gì? truy vấn gì?','<b>Xác định thực thể</b> → bảng.','Chọn <b>khoá chính</b> cho từng bảng.','Xác định <b>mối liên kết</b> → khoá ngoài.','Chọn <b>kiểu dữ liệu</b> và <b>ràng buộc</b>.','<b>Tạo</b> bằng SQL, <b>nhập thử</b>, kiểm tra.'],6)),KEY('Nguyên tắc: mỗi bảng <b>một chủ đề</b>, mỗi thông tin <b>lưu một nơi</b>.')))
S+=END(c,B,['<b>Khoá chính</b>: duy nhất, không NULL; <b>khoá ngoài</b>: tham chiếu khoá chính bảng khác.','<b>Toàn vẹn tham chiếu</b>: không thêm con không có cha; không xoá cha còn con.','<b>NOT NULL, UNIQUE, CHECK, DEFAULT</b> bảo vệ dữ liệu.','Kiểu: INT, REAL/DECIMAL, VARCHAR, DATE, BOOLEAN.','So sánh NULL bằng <b>IS NULL</b>.'],[('Không rỗng','NOT NULL'),('Không trùng','UNIQUE'),('Giới hạn giá trị','CHECK'),('Liên kết bảng','FOREIGN KEY')],'Khoá chính không được NULL; khoá ngoài có thể NULL.',['Khoá chính <b>phức hợp</b> cho bảng trung gian.','<code>DECIMAL</code> chính xác hơn <code>FLOAT</code> với tiền.','<code>UNIQUE</code> khác khoá chính: cho phép <b>một</b> (hoặc nhiều) NULL tuỳ hệ.','Khoá <b>thay thế</b> (surrogate) như số tự tăng <code>AUTOINCREMENT</code>.'],['<b>Chuẩn hoá</b> 1NF, 2NF, 3NF.','<b>Index</b> (chỉ mục) tăng tốc tìm kiếm.','<b>Giao dịch</b> (transaction): ACID.'],
 [('Chọn khoá chính phù hợp cho bảng HOCSINH. Vì sao không chọn họ tên?',),('Khoá ngoài là gì? Nêu một ví dụ.',),('Viết lệnh tạo bảng MONHOC(mamon, tenmon, sotiet) với mamon là khoá chính, tenmon không rỗng, sotiet &gt; 0.',),('Điểm nhập vào phải từ 0 đến 10: dùng ràng buộc nào?',),('Chọn kiểu dữ liệu cho: số điện thoại, giá bán, ngày sinh, giới tính.',)],
 [('<b>mahs</b> (mã học sinh), vì họ tên có thể trùng.',),('Trường tham chiếu khoá chính của bảng khác. Ví dụ <b>HOCSINH.lop</b> → <b>LOP.malop</b>.',),('<code>CREATE TABLE monhoc(mamon TEXT PRIMARY KEY, tenmon TEXT NOT NULL, sotiet INT CHECK (sotiet &gt; 0));</code>',),('<code>CHECK (diem BETWEEN 0 AND 10)</code>',),('VARCHAR(15); DECIMAL(10,0) hoặc INT; DATE; CHAR(1) hoặc VARCHAR.',)],
 [('Bảng DONHANG(madon, makh, ngay) với makh tham chiếu KHACHHANG. Viết CREATE TABLE đầy đủ cho DONHANG.',),('Cho bảng DIEM(mahs, mamon, diem) với khoá chính (mahs, mamon). Thêm hai dòng (HS01, TIN, 9) và (HS01, TIN, 8) được không? Vì sao?',),('Đúng hay sai: (a) Khoá ngoài phải khác NULL. (b) Một bảng có nhiều khoá ngoài được. (c) <code>WHERE diem = NULL</code> chọn các dòng chưa có điểm. (d) CHECK có thể kiểm tra liên quan nhiều cột.',),('Phân tích lỗi thiết kế: bảng HOADON(mahd, makh, tenkh, diachikh, tongtien) lưu cả tên và địa chỉ khách.',),('Khi xoá một lớp trong LOP còn 30 học sinh, các lựa chọn xử lí tham chiếu là gì?',),('Vì sao nên dùng mã số thay vì tên để làm khoá chính?',)],
 [('<code>CREATE TABLE donhang(madon INT PRIMARY KEY, makh INT NOT NULL, ngay DATE, FOREIGN KEY (makh) REFERENCES khachhang(makh));</code>',),('<b>Không</b>: (HS01, TIN) trùng khoá chính phức hợp.',),('(a) <b>Sai</b> (có thể NULL nếu cho phép). (b) <b>Đúng</b>. (c) <b>Sai</b>: phải dùng IS NULL. (d) <b>Đúng</b> (CHECK mức bảng).',),('<b>Dư thừa</b>: tên, địa chỉ khách lặp ở mọi hoá đơn, dễ mâu thuẫn. Tách bảng KHACHHANG(makh, tenkh, diachikh); HOADON chỉ giữ <b>makh</b>.',),('<b>RESTRICT</b> (cấm xoá), <b>CASCADE</b> (xoá cả học sinh), <b>SET NULL</b> (đặt lớp của học sinh là NULL).',),('Mã <b>ngắn, duy nhất, ít đổi</b>; họ tên dài, có thể trùng và có thể đổi.',)],hper=2)
